1: /**
2:  * 将后端返回的站内绝对路径（如 /zhi2/xxx、/uploads/xxx）转为浏览器可请求的完整 URL。
3:  * 去掉首部的 / 后，按「相对当前页面地址」解析（与 import 的相对路径规则一致），部署在 /sz 等子路径下会自动落在正确前缀下，无需 VITE_APP_PUBLIC_PATH。
4:  * 已是 http(s)://、//、data:、blob: 的路径，以及不以 / 开头的地址（含 import 静态资源）均原样返回。
5:  * 站点入口建议配置为带尾斜杠的地址（如 …/sz/），避免出现 …/sz 无斜杠时浏览器把最后一段当「文件名」导致相对路径拼错。
6:  */
7: export function resolveServerAssetUrl(input) {
8:   if (input == null || input === '') return ''
9:   const path = String(input).trim()
10:   if (!path) return ''
11: 
12:   if (/^(https?:\/\/|\/\/|data:|blob:)/i.test(path)) {
13:     return path
14:   }
15: 
16:   if (!path.startsWith('/')) {
17:     return path
18:   }
19: 
20:   if (path.startsWith('/@') || path.startsWith('/src/')) {
21:     return path
22:   }
23: 
24:   if (typeof window === 'undefined' || !window.location) {
25:     return path
26:   }
27: 
28:   const relative = path.replace(/^\/+/, '')
29:   try {
30:     return new URL(relative, window.location.href).href
31:   } catch {
32:     return path
33:   }
34: }
