64: function autoInstall() {
65:   const installer = path.join(repoRoot, "scripts", "install.mjs");
66:   if (!fs.existsSync(installer)) {
67:     return false;
68:   }
69: 
70:   console.log("[vite-build] 未找到 vite，正在仓库根目录安装依赖…");
71:   const result = spawnSync(process.execPath, [installer], {
72:     stdio: "inherit",
73:     cwd: repoRoot,
74:   });
75: 
76:   if (result.status !== 0) {
77:     console.error(`[vite-build] 自动安装依赖失败（退出码 ${result.status ?? "unknown"}）`);
78:     return false;
79:   }
80:   return true;
81: }
