83: function tryResolveViteBin() {
84:   // 先在本项目内的固定位置找，不依赖 import.meta.resolve 的逐级向上查找：
85:   // 宿主机/上层目录若残留无关的全局 vite，向上查找会先命中它，导致误判。
86:   const localCandidates = [
87:     path.join(pkgDir, "node_modules", "vite", "package.json"),
88:     path.join(repoRoot, "node_modules", "vite", "package.json"),
89:   ];
90: 
91:   let vitePkgJsonPath = localCandidates.find((p) => fs.existsSync(p));
92: 
93:   if (!vitePkgJsonPath) {
94:     // 项目内没有，退回 Node 的解析（例如被放在非标准位置的真实安装）
95:     try {
96:       vitePkgJsonPath = fileURLToPath(import.meta.resolve("vite/package.json"));
97:     } catch {
98:       return { ok: false };
99:     }
100:   }
101: 
102:   const vitePkgDir = path.dirname(vitePkgJsonPath);
103: 
104:   // 只接受本包或仓库根下的 vite，避免命中宿主机/上层的无关全局安装
105:   const allowed = isInside(pkgDir, vitePkgDir) || isInside(path.join(repoRoot, "node_modules"), vitePkgDir);
106:   if (!allowed) {
107:     return { ok: false, reason: "outside", vitePkgDir };
108:   }
109: 
110:   const actualVersion = readJson(vitePkgJsonPath)?.version;
111:   if (declaredViteRange && actualVersion && actualVersion !== declaredViteRange.replace(/^[\^~=]/, "")) {
112:     return { ok: false, reason: "version", vitePkgDir, actualVersion };
113:   }
114: 
115:   const bin = path.join(vitePkgDir, "bin/vite.js");
116:   if (!fs.existsSync(bin)) {
117:     return { ok: false, reason: "bin", vitePkgDir };
118:   }
119:   return { ok: true, bin };
120: }
121: 
122: function resolveViteBin() {
123:   let res = tryResolveViteBin();
124: 
125:   // 依赖缺失时自动安装一次后重试：CI 可能只执行 `npm run test`，没有独立安装阶段
126:   if (!res.ok && res.reason !== "version" && res.reason !== "bin") {
127:     if (autoInstall()) {
128:       res = tryResolveViteBin();
129:     }
130:   }
131: 
132:   if (!res.ok) {
