goHome() {
  const backToPortal = () => {
    // 从对内主页进入大屏时按浏览器历史后退，回到进入前的对内主页；
    // 直接打开/新标签打开（没有可回退的站内历史）时兜底跳到对内主页 /index。
    const hasSpaHistory = window.history.length > 1 && !!window.history.state
    if (hasSpaHistory) {
      this.$router.go(-1)
    } else {
      this.$router.replace({ path: '/index' })
    }
  }
  // 首页入口进入大屏时会自动进入浏览器全屏，先退出再返回，避免回到门户后残留全屏
  if (document.fullscreenElement && document.exitFullscreen) {
    document.exitFullscreen().then(backToPortal).catch(backToPortal)
  } else {
    backToPortal()
  }
},

