/**
 * 临时验证：市场监测大屏「logo 读配置 / 返回首页回对内主页」
 * 运行：node verify-logo-home.cjs   （在 nginx 8092 站点部署后）
 */
const assert = require('assert')
const { chromium } = require('D:/repository/门户/node_modules/playwright')

const BASE = 'http://127.0.0.1:8092/index.html'
const MM = BASE + '#/market-monitor'
const RED_LOGO =
  'data:image/svg+xml;base64,' +
  Buffer.from(
    '<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28"><rect width="28" height="28" fill="#ff0000"/></svg>'
  ).toString('base64')

const results = []
function ok(name, detail) {
  results.push({ name, ok: true, detail })
  console.log(`  PASS  ${name}${detail ? ' — ' + detail : ''}`)
}
function fail(name, err) {
  results.push({ name, ok: false, detail: String(err) })
  console.log(`  FAIL  ${name} — ${err}`)
}

async function open(browser, sysLogo) {
  const context = await browser.newContext({ viewport: { width: 1920, height: 1080 } })
  if (sysLogo !== undefined) {
    await context.addInitScript({
      content: `localStorage.setItem('platform-config-cache', ${JSON.stringify(
        JSON.stringify({ data: { sysLogo, region: '320500' }, savedAt: Date.now() })
      )})`
    })
  }
  // 用稳定的成功响应桩化业务接口：避免「接口失败 → 全局异常提示弹窗」挡住按钮，
  // 同时让测试只由注入的缓存决定 sysLogo。
  await context.route('**/api/**', (route) => {
    const isConfig = route.request().url().includes('platformConfig/getInfo')
    const data = isConfig ? { region: '320500', platformName: '苏州房产综合服务平台' } : {}
    return route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ code: 200, msg: 'ok', data })
    })
  })
  const page = await context.newPage()
  const pageErrors = []
  page.on('pageerror', (e) => pageErrors.push(String(e)))
  await page.goto(MM, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.waitForSelector('header .w-9.h-9', { timeout: 30000 })
  await page.waitForTimeout(900)
  return { context, page, pageErrors }
}

const box = 'header .w-9.h-9'

async function main() {
  const browser = await chromium.launch({ headless: true })
  try {
    // 1) 未配置 sysLogo：兜底静态 SVG 图标
    {
      const { context, page } = await open(browser)
      try {
        const svgCount = await page.locator(`${box} > svg`).count()
        const imgCount = await page.locator(`${box} > img`).count()
        assert.strictEqual(svgCount, 1, `兜底 SVG 数量=${svgCount}`)
        assert.strictEqual(imgCount, 0, `不应渲染 img，实际=${imgCount}`)
        ok('1 未配置 sysLogo → 显示原静态图标', 'svg=1 img=0')
      } catch (e) { fail('1 未配置 sysLogo 兜底', e) }
      await context.close()
    }

    // 2) 配置 sysLogo：渲染配置图片，静态图标消失
    {
      const { context, page } = await open(browser, RED_LOGO)
      try {
        const imgCount = await page.locator(`${box} > img`).count()
        const svgCount = await page.locator(`${box} > svg`).count()
        assert.strictEqual(imgCount, 1, `配置图片数量=${imgCount}`)
        assert.strictEqual(svgCount, 0, `静态图标应消失，实际=${svgCount}`)
        const src = await page.locator(`${box} > img`).getAttribute('src')
        assert.strictEqual(src, RED_LOGO, 'img src 应为 resolveServerAssetUrl(sysLogo)')
        ok('2 配置 sysLogo → 渲染配置图片', 'img=1 svg=0，src 与配置一致')
      } catch (e) { fail('2 配置 sysLogo 渲染', e) }
      await context.close()
    }

    // 3) sysLogo 地址不可用：@error 兜底回静态图标
    {
      const { context, page } = await open(browser, '/__missing_logo_verify__.png')
      try {
        await page.waitForFunction(
          () => {
            const el = document.querySelector('header .w-9.h-9')
            return el && !!el.querySelector('svg') && !el.querySelector('img')
          },
          { timeout: 8000 }
        )
        ok('3 sysLogo 加载失败 → 回退静态图标', '破图不残留')
      } catch (e) { fail('3 sysLogo 加载失败兜底', e) }
      await context.close()
    }

    // 4) 直接打开大屏（无站内来源）：返回首页兜底回对内主页 /index
    {
      const { context, page, pageErrors } = await open(browser)
      try {
        const dialog = await page.locator('.el-message-box__wrapper').count()
        assert.strictEqual(dialog, 0, '不应出现全局异常弹窗')
        await page.getByRole('button', { name: '返回首页' }).click()
        await page.waitForFunction(
          () => !location.hash.includes('/market-monitor'),
          { timeout: 15000 }
        )
        const url = page.url()
        assert(/#\/(index|UnifiedLogin)/.test(url), `未回到对内主页，url=${url}`)
        ok('4 直接打开 → 返回首页回对内主页', `url=${url.split('#')[1]}`)
        assert.strictEqual(pageErrors.length, 0, '页面报错: ' + pageErrors.join(' | '))
      } catch (e) { fail('4 直接打开返回首页', e) }
      await context.close()
    }

    // 5) 从门户内页 SPA 跳转进入大屏：按浏览器历史后退（回到进入前的页面）
    {
      const { context, page } = await open(browser)
      try {
        const push = (path) => page.evaluate(
          (p) => document.querySelector('#app').__vue__.$router.push(p),
          path
        )
        await push('/privacy')
        await page.waitForFunction(() => location.hash.includes('/privacy'), { timeout: 15000 })
        await push('/market-monitor')
        await page.waitForFunction(() => location.hash.includes('/market-monitor'), { timeout: 15000 })
        await page.waitForTimeout(400)

        const entryFromPath = await page.evaluate(() => {
          const find = (vm) => {
            if (!vm) return null
            if (vm.$options && vm.$options.name === 'MarketMonitorIndex') return vm
            for (const c of vm.$children || []) {
              const hit = find(c)
              if (hit) return hit
            }
            return null
          }
          const vm = find(document.querySelector('#app').__vue__)
          return vm ? vm.entryFromPath : '__NOT_FOUND__'
        })
        assert.strictEqual(entryFromPath, '/privacy', `beforeRouteEnter 未记录来源：${entryFromPath}`)

        await page.getByRole('button', { name: '返回首页' }).click()
        await page.waitForFunction(() => location.hash.includes('/privacy'), { timeout: 15000 })
        ok('5 SPA 进入 → 返回首页按历史后退', `entryFromPath=/privacy，回退到 ${page.url().split('#')[1]}`)
      } catch (e) { fail('5 SPA 历史后退', e) }
      await context.close()
    }
  } finally {
    await browser.close()
  }

  const failed = results.filter((r) => !r.ok)
  console.log(`\n结果：${results.length - failed.length}/${results.length} 通过`)
  if (failed.length) process.exit(1)
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

