const { chromium } = require('D:/repository/门户/node_modules/playwright')
const fs = require('fs')
const path = require('path')
const assert = require('assert')

const dir = 'D:/repository/门户/dist/assets'
let goHome = 0
let entry = 0
for (const f of fs.readdirSync(dir).filter((n) => n.endsWith('.js'))) {
  const c = fs.readFileSync(path.join(dir, f), 'utf8')
  if (c.includes('go-home')) goHome++
  if (c.includes('entryFromPath')) entry++
}
console.log(`built markers: go-home=${goHome} chunks, entryFromPath=${entry} chunks`)
assert(goHome >= 1 && entry >= 1, '构建产物缺少本次改动')

;(async () => {
  const b = await chromium.launch({ headless: true })
  const c = await b.newContext({ viewport: { width: 1920, height: 1080 } })
  const p = await c.newPage()
  await p.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'domcontentloaded', timeout: 60000 })
  await p.waitForSelector('header .w-9.h-9', { timeout: 30000 })
  await p.waitForTimeout(2500)
  const logo = await p.evaluate(() => {
    const box = document.querySelector('header .w-9.h-9')
    const img = box && box.querySelector('img')
    return { hasImg: !!img, w: img ? img.naturalWidth : 0, src: img ? img.getAttribute('src') : null }
  })
  const dialog = await p.locator('.el-message-box__wrapper').count()
  console.log('logo=', JSON.stringify(logo), 'dialog=', dialog)
  assert(logo.hasImg && logo.w > 0, '未按配置渲染 logo')
  assert.strictEqual(dialog, 0, '出现全局异常弹窗')

  await p.getByRole('button', { name: '返回首页' }).click()
  await p.waitForFunction(() => !location.hash.includes('/market-monitor'), { timeout: 15000 })
  const url = p.url()
  console.log('after 返回首页:', url.split('#')[1])
  assert(/#\/(index|UnifiedLogin)/.test(url), '未回到对内主页')
  await b.close()
  console.log('最终验收：3/3 通过')
})().catch((e) => { console.error(e); process.exit(1) })
